"""
    Calculates mean percentage error for fitted values to estimated values.

    :param estimated: estimated values
    :param fitted: fitted values
    :return: percent error
    """
def error(estimated: Any, fitted: Any) -> object {
    return (
        sum([abs(((e / f) - 1)) for (e, f) in zip(estimated, fitted)]) / len(estimated)
    );
}

"""Splits string and returns splitted substring. Returns "" if None


  Args:
    st: String to split
    pos: Position to return. Can be negative
    sep: Separator
  """
def strtoken(st: Any, pos: Any, sep: Any) -> object {
    out = "";
    s = st.split(sep);
    if ((len(s) >= abs(pos)) and (pos != 0)) {
        if (pos > 0) {
            out = s[(pos - 1)];
        } else {
            out = s[(len(s) + pos)];
        }
    }
    return out;
}

